const indonesianTemplates = Object.entries(indonesian).filter(([key]) =>
  /\{\d+\}/.test(key),
);
const templateEntries = (entries: [string, string][]) =>
  entries
    .filter(([key]) => /\{\d+\}/.test(key))
    .map(([key, target]) => {
      const indexes: string[] = [];
      const pattern = key
        .split(/(\{\d+\})/)
        .map((part) => {
          const match = part.match(/^\{(\d+)\}$/);
          if (match) {
            indexes.push(match[1]);
            return "(.*?)";
          }
          return part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        })
        .join("");
      return { pattern: new RegExp("^" + pattern + "$"), target, indexes };
    });
const templates = {
  en: templateEntries(Object.entries(english)),
  id: templateEntries(indonesianTemplates),
};
export function translate(
  source: string,
  locale: Locale = "id",
  values: Record<string, unknown> = {},
) {
  const normalized = source.replace(/\s+/g, " ").trim();
  const catalog = locale === "en" ? english : indonesian;
  let translated = catalog[normalized] ?? normalized;
  if (!catalog[normalized])
    for (const template of templates[locale]) {
      const match = normalized.match(template.pattern);
      if (match) {
        translated = template.target.replace(
          /\{(\d+)\}/g,
          (all, key) => match[template.indexes.indexOf(key) + 1] ?? all,
        );
        break;
      }
    }
  return (
    (/^\s/.test(source) ? " " : "") +
    translated.replace(/\{(\d+)\}/g, (all, key) =>
      Object.prototype.hasOwnProperty.call(values, key)
        ? String(values[key])
        : all,
    ) +
    (/\s$/.test(source) ? " " : "")
  );
}
